import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Environment Variables (.env) Reference","description":"Every relevant .env key with its default from .env.example, what it controls in the kits, the differences between kits and a production checklist.","frontmatter":{"title":"Environment Variables (.env) Reference","description":"Every relevant .env key with its default from .env.example, what it controls in the kits, the differences between kits and a production checklist.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/reference/environment.html"}],["meta",{"property":"og:title","content":"Environment Variables (.env) Reference"}],["meta",{"property":"og:description","content":"Every relevant .env key with its default from .env.example, what it controls in the kits, the differences between kits and a production checklist."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/reference/environment.html"}],["meta",{"name":"twitter:title","content":"Environment Variables (.env) Reference"}],["meta",{"name":"twitter:description","content":"Every relevant .env key with its default from .env.example, what it controls in the kits, the differences between kits and a production checklist."}]]},"headers":[],"relativePath":"docs/reference/environment.md","filePath":"docs/reference/environment.md","lastUpdated":1790486087000}'),a={name:"docs/reference/environment.md"};function r(n,t,i,s,l,h){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h1><p>Defaults below are from the Vue kit&#39;s <code>.env.example</code>. The other kits differ only in these keys:</p><table tabindex="0"><thead><tr><th>Key</th><th>Vue</th><th>React</th><th>Svelte</th></tr></thead><tbody><tr><td><code>APP_URL</code></td><td><code>http://vue.test</code></td><td><code>https://react.test</code></td><td><code>https://svelte.test</code></td></tr><tr><td><code>APP_DOMAIN</code></td><td><code>vue.test</code></td><td><code>react.test</code></td><td><code>svelte.test</code></td></tr><tr><td><code>DB_DATABASE</code></td><td><code>saas_laravel_vue</code></td><td><code>saas_laravel_recat</code></td><td><code>saas_laravel_svelte</code></td></tr><tr><td><code>DB_PASSWORD</code></td><td>set to a sample value</td><td>empty</td><td>empty</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Change <code>APP_URL</code>, <code>APP_DOMAIN</code> and the <code>DB_*</code> keys first. Most other defaults work as is for local development.</p></div><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to &quot;Application&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>APP_NAME</code></td><td><code>Laravel</code></td><td>Central app name. Tenant domains override it with the domain&#39;s App name or company.</td></tr><tr><td><code>APP_ENV</code></td><td><code>local</code></td><td>In <code>production</code>: strict password rules, destructive DB commands prohibited, full error pages</td></tr><tr><td><code>APP_KEY</code></td><td>empty</td><td><code>php artisan key:generate</code>. Also signs maintenance bypass cookies and is the default passkey user handle secret.</td></tr><tr><td><code>APP_DEBUG</code></td><td><code>true</code></td><td><code>false</code> in production</td></tr><tr><td><code>APP_URL</code></td><td><code>http://vue.test</code></td><td>Central URL. Scheme is reused for tenant links; host is the passkey relying party.</td></tr><tr><td><code>APP_DOMAIN</code></td><td><code>vue.test</code></td><td>Central domain; tenant domains are <code>&lt;sub&gt;.APP_DOMAIN</code></td></tr><tr><td><code>APP_LOCALE</code></td><td><code>en</code></td><td>Default language when neither the user nor the domain sets one</td></tr><tr><td><code>APP_FALLBACK_LOCALE</code></td><td><code>en</code></td><td></td></tr><tr><td><code>APP_FAKER_LOCALE</code></td><td><code>en_US</code></td><td></td></tr><tr><td><code>APP_MAINTENANCE_DRIVER</code></td><td><code>file</code></td><td>Laravel&#39;s own <code>php artisan down</code> (not tenant maintenance)</td></tr><tr><td><code>BCRYPT_ROUNDS</code></td><td><code>12</code></td><td></td></tr></tbody></table><h2 id="tenancy" tabindex="-1">Tenancy <a class="header-anchor" href="#tenancy" aria-label="Permalink to &quot;Tenancy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>TENANCY_DB_PREFIX</code></td><td><code>tenant</code></td><td><strong>React kit only</strong> (<code>config/tenancy.php</code>). Vue and Svelte hardcode <code>&#39;prefix&#39; =&gt; &#39;tenant&#39;</code>; edit the config or switch it to <code>env()</code>. Use a unique prefix when several apps share one MySQL server.</td></tr></tbody></table><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>DB_CONNECTION</code></td><td><code>mysql</code></td><td>Also the central tenancy connection</td></tr><tr><td><code>DB_HOST</code></td><td><code>127.0.0.1</code></td><td></td></tr><tr><td><code>DB_PORT</code></td><td><code>3306</code></td><td></td></tr><tr><td><code>DB_DATABASE</code></td><td><code>saas_laravel_vue</code></td><td>Central database; create it before migrating</td></tr><tr><td><code>DB_USERNAME</code></td><td><code>root</code></td><td>Needs <code>CREATE DATABASE</code> rights for tenants</td></tr><tr><td><code>DB_PASSWORD</code></td><td>sample value (Vue), empty (React, Svelte)</td><td>Replace with your own</td></tr></tbody></table><h2 id="session-cache-queue" tabindex="-1">Session, cache, queue <a class="header-anchor" href="#session-cache-queue" aria-label="Permalink to &quot;Session, cache, queue&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>SESSION_DRIVER</code></td><td><code>database</code></td><td>Stored in the current context&#39;s DB (tenant sessions in tenant DBs)</td></tr><tr><td><code>SESSION_LIFETIME</code></td><td><code>120</code></td><td>Minutes</td></tr><tr><td><code>SESSION_ENCRYPT</code></td><td><code>false</code></td><td></td></tr><tr><td><code>SESSION_PATH</code></td><td><code>/</code></td><td></td></tr><tr><td><code>SESSION_DOMAIN</code></td><td><code>null</code></td><td>Sessions are per host, so central and tenant logins are separate</td></tr><tr><td><code>CACHE_STORE</code></td><td><code>database</code></td><td></td></tr><tr><td><code>QUEUE_CONNECTION</code></td><td><code>database</code></td><td>Invitation and reset emails are queued</td></tr><tr><td><code>DB_QUEUE_CONNECTION</code></td><td>not set (falls back to <code>DB_CONNECTION</code>)</td><td>Keep jobs in the central <code>jobs</code> table so one worker serves all tenants</td></tr><tr><td><code>BROADCAST_CONNECTION</code></td><td><code>log</code></td><td></td></tr><tr><td><code>FILESYSTEM_DISK</code></td><td><code>local</code></td><td><code>local</code> and <code>public</code> are suffixed per tenant</td></tr></tbody></table><h2 id="mail" tabindex="-1">Mail <a class="header-anchor" href="#mail" aria-label="Permalink to &quot;Mail&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>MAIL_MAILER</code></td><td><code>log</code></td><td>Emails go to <code>storage/logs/laravel.log</code>. Use <code>smtp</code> (or another transport) to deliver.</td></tr><tr><td><code>MAIL_SCHEME</code></td><td><code>null</code></td><td></td></tr><tr><td><code>MAIL_HOST</code></td><td><code>127.0.0.1</code></td><td></td></tr><tr><td><code>MAIL_PORT</code></td><td><code>2525</code></td><td></td></tr><tr><td><code>MAIL_USERNAME</code> / <code>MAIL_PASSWORD</code></td><td><code>null</code></td><td></td></tr><tr><td><code>MAIL_FROM_ADDRESS</code></td><td><code>hello@example.com</code></td><td></td></tr><tr><td><code>MAIL_FROM_NAME</code></td><td><code>${APP_NAME}</code></td><td></td></tr></tbody></table><h2 id="other-keys-in-env-example" tabindex="-1">Other keys in <code>.env.example</code> <a class="header-anchor" href="#other-keys-in-env-example" aria-label="Permalink to &quot;Other keys in `.env.example`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th></tr></thead><tbody><tr><td><code>LOG_CHANNEL</code> / <code>LOG_STACK</code> / <code>LOG_LEVEL</code></td><td><code>stack</code> / <code>single</code> / <code>debug</code></td></tr><tr><td><code>REDIS_CLIENT</code> / <code>REDIS_HOST</code> / <code>REDIS_PORT</code></td><td><code>phpredis</code> / <code>127.0.0.1</code> / <code>6379</code></td></tr><tr><td><code>MEMCACHED_HOST</code></td><td><code>127.0.0.1</code></td></tr><tr><td><code>AWS_*</code></td><td>empty (<code>AWS_DEFAULT_REGION=us-east-1</code>)</td></tr><tr><td><code>VITE_APP_NAME</code></td><td><code>${APP_NAME}</code> (page title suffix on the frontend)</td></tr></tbody></table><h2 id="optional-keys-read-by-config" tabindex="-1">Optional keys read by config <a class="header-anchor" href="#optional-keys-read-by-config" aria-label="Permalink to &quot;Optional keys read by config&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>File</th></tr></thead><tbody><tr><td><code>PASSKEYS_USER_HANDLE_SECRET</code></td><td><code>APP_KEY</code></td><td><code>config/fortify.php</code></td></tr><tr><td><code>AUTH_PASSWORD_TIMEOUT</code></td><td><code>10800</code></td><td><code>config/auth.php</code></td></tr><tr><td><code>DB_QUEUE_TABLE</code> / <code>DB_QUEUE</code> / <code>DB_QUEUE_RETRY_AFTER</code></td><td><code>jobs</code> / <code>default</code> / <code>90</code></td><td><code>config/queue.php</code></td></tr></tbody></table><h2 id="production-checklist" tabindex="-1">Production checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Production value</th></tr></thead><tbody><tr><td><code>APP_ENV</code></td><td><code>production</code></td></tr><tr><td><code>APP_DEBUG</code></td><td><code>false</code></td></tr><tr><td><code>APP_URL</code></td><td><code>https://your-domain.com</code></td></tr><tr><td><code>APP_DOMAIN</code></td><td><code>your-domain.com</code></td></tr><tr><td><code>MAIL_MAILER</code></td><td><code>smtp</code> (or another real transport)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Also before going live</p><ul><li>Run a queue worker (<code>php artisan queue:work</code>); invitation and reset emails are queued.</li><li>Point <code>*.your-domain.com</code> at the app (wildcard DNS and TLS certificate).</li><li>Remove or change the seeded default users.</li></ul></div>',21)])])}const _=e(a,[["render",r]]);export{u as __pageData,_ as default};
